css_changes:
.lc-top{display:grid;grid-template-columns:auto minmax(0,1fr) auto;grid-template-rows:auto 1fr;
  grid-template-areas:"rank title wr" ". legs wr";gap:16px;align-items:start}
.lc-rank{grid-area:rank}.lc-title-wrap{grid-area:title}.lc-wr{grid-area:wr}
.lc-top>.legs{grid-area:legs;margin:0;min-width:0}

/* Card reading order stacks before the fixed evidence rail crowds the signal criteria. */
@media(max-width:767px){
  .lc-top{grid-template-columns:auto minmax(0,1fr);grid-template-rows:auto auto auto;
    grid-template-areas:"rank title" "legs legs" "wr wr"}
  .lc-wr{width:100%;gap:var(--sp-3,12px)}
}
/* responsive */
@media(max-width:640px){

template_inverse_manifest.moved_block:
{# the line-up: each leg lined up, timeframe-tagged #}
<div class="legs">
  {% for leg in c.legs %}
  <div class="leg">
    {% if leg.tf == 'W' %}
    <span class="leg-tf w" tabindex="0"
          data-tip-en="This leg is evaluated on weekly bars. Its indicator lookback and trigger frequency are separate properties."
          data-tip-zh="此条件在周线数据上计算；指标回看窗口和触发频率是不同的属性。">W</span>
    {% else %}
    <span class="leg-tf d" tabindex="0"
          data-tip-en="This leg is evaluated on daily bars. The indicator itself may use a longer lookback."
          data-tip-zh="此条件在日线数据上计算；指标本身可能使用更长的回看窗口。">D</span>
    {% endif %}
    <span class="leg-txt"><span class="l-en">{{ leg.en }}</span><span class="l-zh">{{ leg.zh }}</span></span>
  </div>
  {% endfor %}
</div>
